const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

const app = express();

// Configure storage - files go to public uploads directory
const storage = multer.diskStorage({
  destination: function (req, file, cb) {
    const uploadDir = path.join(__dirname, 'public', 'uploads');
    if (!fs.existsSync(uploadDir)) {
      fs.mkdirSync(uploadDir, { recursive: true });
    }
    cb(null, uploadDir);
  },
  filename: function (req, file, cb) {
    // Preserve original extension for user convenience
    const ext = path.extname(file.originalname);
    const basename = crypto.randomBytes(16).toString('hex');
    cb(null, basename + ext);
  }
});

// Basic file size limit only
const upload = multer({
  storage: storage,
  limits: { fileSize: 10 * 1024 * 1024 } // 10MB max
});

// Middleware to log uploads
app.use((req, res, next) => {
  if (req.method === 'POST') {
    console.log(`[${new Date().toISOString()}] Upload attempt from ${req.ip}`);
  }
  next();
});

// Upload endpoint - accepts any file type
app.post('/api/upload', upload.single('file'), (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file provided' });
  }

  const fileUrl = `/uploads/${req.file.filename}`;

  // Log file metadata
  console.log(`Uploaded: ${req.file.originalname} -> ${req.file.filename} (${req.file.mimetype})`);

  res.json({
    success: true,
    filename: req.file.filename,
    originalName: req.file.originalname,
    size: req.file.size,
    url: fileUrl
  });
});

// Serve uploaded files statically
app.use('/uploads', express.static(path.join(__dirname, 'public', 'uploads')));

// Gallery page showing recent uploads
app.get('/gallery', (req, res) => {
  const uploadDir = path.join(__dirname, 'public', 'uploads');
  let files = [];
  if (fs.existsSync(uploadDir)) {
    files = fs.readdirSync(uploadDir).map(f => ({
      name: f,
      url: `/uploads/${f}`,
      ext: path.extname(f).toLowerCase()
    }));
  }
  res.json({ files });
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`File upload service running on port ${PORT}`);
});
